import{_ as e,C as a,c as o,o as r,a0 as i,b as t,w as s,a as n,G as l,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Asesoramiento técnico","description":"","frontmatter":{},"headers":[],"relativePath":"es/technical/index.md","filePath":"es/technical/index.md"}');const d=e({name:"es/technical/index.md"},[["render",function(e,u,d,p,m,b){const f=a("Mermaid");return r(),o("div",null,[u[2]||(u[2]=i('<h1 id="asesoramiento-tecnico" tabindex="-1">Asesoramiento técnico <a class="header-anchor" href="#asesoramiento-tecnico" aria-label="Permalink to &quot;Asesoramiento técnico&quot;">​</a></h1><h2 id="una-nota-sobre-la-tecnica" tabindex="-1">Una nota sobre la técnica <a class="header-anchor" href="#una-nota-sobre-la-tecnica" aria-label="Permalink to &quot;Una nota sobre la técnica&quot;">​</a></h2><p>Si bien nuestro enfoque principal está en el juego mental y el estado de flujo, reconocemos que la técnica es la base sobre la que se construye todo lo demás.</p><div class="info custom-block"><p class="custom-block-title">Nuestra filosofía</p><p><strong>La técnica es la base, pero el flujo es el techo.</strong> Necesitas una técnica sólida para alcanzar el nivel de élite, pero el dominio mental es lo que te lleva más allá.</p></div>',4)),(r(),t(c,null,{default:s(()=>[l(f,{id:"mermaid-14",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BMaestr%C3%ADa%20en%20petanca%5D%20--%3E%20B%5BFundaci%C3%B3n%20T%C3%A9cnica%5D%0A%20%20%20%20A%20--%3E%20C%5BJuego%20mental%5D%0A%0A%20%20%20%20B%20--%3E%20D%5BT%C3%A9cnica%20s%C3%B3lida%5D%0A%20%20%20%20D%20--%3E%20E%5BMeseta%5D%0A%0A%20%20%20%20C%20--%3E%20F%5BEstado%20de%20flujo%5D%0A%20%20%20%20F%20--%3E%20G%5BM%C3%A1ximo%20rendimiento%5D%0A%0A%20%20%20%20B%20--%3E%20C%0A%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A%20%20%20%20style%20G%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...u[0]||(u[0]=[n(" Loading... ",-1)])]),_:1})),u[3]||(u[3]=i('<h2 id="el-error-mas-comun-en-la-formacion-tecnica" tabindex="-1">El error más común en la formación técnica <a class="header-anchor" href="#el-error-mas-comun-en-la-formacion-tecnica" aria-label="Permalink to &quot;El error más común en la formación técnica&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Esta sección es para jugadores experimentados</p><p>Si eres nuevo en la petanca, naturalmente necesitarás desarrollar tu técnica básica desde cero, y ese es un viaje diferente.</p><p><strong>Este consejo es para jugadores que llevan años jugando</strong> y ya tienen una técnica establecida que les resulta natural, relajada y fiable. Ya has encontrado tu estilo de lanzamiento. Ahora la pregunta es: ¿cómo progresas a partir de ahí?</p></div><div class="warning custom-block"><p class="custom-block-title">La trampa común</p><p>Cuando los jugadores experimentados quieren mejorar, suelen volver a lo básico: ajustar el agarre, el movimiento del brazo, el punto de lanzamiento y la posición del cuerpo. Horas de práctica. Ajustes sin fin.</p><p><strong>Pero se han saltado la pregunta más importante:</strong> ¿Qué quieres exactamente que haga la bola?</p></div><p>Antes de abordar tu técnica, necesitas tener claro el <strong>resultado</strong> que quieres lograr. No &quot;Quiero golpear más&quot; ni &quot;Quiero ser más consistente&quot;; esos no son resultados, son deseos.</p><p>Un resultado real se ve así:</p><ul><li>&quot;Quiero un globo de arco alto que se detenga a 20 cm de donde aterriza&quot;</li><li>&quot;Quiero un plano rodante que se curve hacia la izquierda en este tipo de terreno&quot;</li><li>&quot;Quiero un tiro suave y frontal que apenas toque la bola objetivo&quot;</li></ul><p><strong>Primero, explora la <a href="/es/technical/throws">Paleta de Lanzamientos</a></strong> para comprender las posibilidades. Luego, decide qué lanzamiento específico quieres añadir a tu repertorio. Solo entonces deberías empezar a trabajar en cómo deben moverse tu brazo, muñeca y cuerpo para lograr ese resultado.</p><h2 id="la-forma-correcta-de-trabajar-la-tecnica" tabindex="-1">La forma correcta de trabajar la técnica <a class="header-anchor" href="#la-forma-correcta-de-trabajar-la-tecnica" aria-label="Permalink to &quot;La forma correcta de trabajar la técnica&quot;">​</a></h2><p>No decimos que nunca debas trabajar el brazo, la muñeca, la liberación ni la posición corporal. <strong>El trabajo técnico de ejecución es absolutamente válido</strong>, pero debe tener el propósito correcto.</p><div class="info custom-block"><p class="custom-block-title">El propósito correcto para el trabajo técnico</p><p><strong>Propósito correcto:</strong> &quot;Quiero agregar un nuevo lanzamiento a mi repertorio&quot;</p><p><strong>Propósito equivocado:</strong> &quot;Quiero acertar más tiros&quot; o &quot;Quiero ser más consistente&quot;</p></div><p>Aquí está el proceso:</p><ol><li><strong>Explora la <a href="/es/technical/throws">Paleta de Lanzamientos</a></strong> — Identifica qué lanzamiento o técnica quieres agregar a tu repertorio</li><li><strong>Visualiza el resultado</strong>: ¿Qué debería hacer la bola? ¿Qué trayectoria, aterrizaje, giro y comportamiento necesitas?</li><li><strong>Luego trabaja en la ejecución</strong>: ahora puedes concentrarte en el brazo, la muñeca, la posición del cuerpo y la liberación para lograr ese resultado específico.</li></ol><p>Este enfoque le da a tu formación técnica <strong>una dirección clara y un progreso medible</strong>. No solo estás practicando, sino que estás ampliando deliberadamente tus capacidades.</p><div class="tip custom-block"><p class="custom-block-title">Ejemplo: Agregar una Plombée</p><p><strong>Objetivo:</strong> Añade un drop shot (plombée) a tu repertorio de puntería</p><p><strong>Visualización del resultado:</strong> La bola debe formar un arco alto, aterrizar suavemente con efecto retroceso y detenerse casi inmediatamente.</p><p><strong>Enfoque técnico:</strong> Punto de liberación más alto, mayor acción de la muñeca para el efecto retroceso, agarre más suave</p><p><strong>Medida de éxito:</strong> ¿Puedes ejecutar este lanzamiento cuando lo desees? Ese es el objetivo.</p></div><h2 id="mejores-tiros-vs-mas-tiros-entendiendo-la-diferencia" tabindex="-1">Mejores tiros vs. Más tiros: Entendiendo la diferencia <a class="header-anchor" href="#mejores-tiros-vs-mas-tiros-entendiendo-la-diferencia" aria-label="Permalink to &quot;Mejores tiros vs. Más tiros: Entendiendo la diferencia&quot;">​</a></h2><p>Hay una distinción crucial que muchos jugadores pasan por alto:</p><div class="tip custom-block"><p class="custom-block-title">La idea clave</p><p><strong>Si quieres hacer MEJORES tiros</strong> → Trabaja en tu técnica</p><p><strong>Si quieres hacer MÁS tiros</strong> → Trabaja tu fuerza mental</p></div><h3 id="¿que-quiere-decir-esto" tabindex="-1">¿Qué quiere decir esto? <a class="header-anchor" href="#¿que-quiere-decir-esto" aria-label="Permalink to &quot;¿Qué quiere decir esto?&quot;">​</a></h3><p><strong>Hacer mejores tiros</strong> significa ampliar tu repertorio técnico:</p><ul><li>Añadiendo nuevos tipos de lanzamientos (plombée, portée, demi-portée)</li><li>Mejorar la precisión en tipos de disparos específicos</li><li>Desarrollar nuevas habilidades que actualmente no tienes</li><li><strong>Esto requiere práctica técnica y entrenamiento físico</strong></li></ul><p><strong>Hacer más tiros</strong> significa ejecutar lo que ya sabes hacer:</p><ul><li>Realizar los tiros que ya puedes hacer en la práctica</li><li>Desempeñarse de manera consistente bajo presión</li><li>Confiar en tu técnica cuando importa</li><li><strong>Esto requiere entrenamiento mental y acceso al estado de flujo</strong></li></ul><h3 id="la-verificacion-de-la-realidad" tabindex="-1">La verificación de la realidad <a class="header-anchor" href="#la-verificacion-de-la-realidad" aria-label="Permalink to &quot;La verificación de la realidad&quot;">​</a></h3><p>Pregúntate honestamente:</p><ul><li>¿Puedes encestar en la práctica estando relajado? ✅ <strong>Entonces tienes la técnica</strong></li><li>¿Te cuesta competir? ⚠️ <strong>Entonces necesitas trabajo mental, no más entrenamiento técnico</strong></li></ul><div class="warning custom-block"><p class="custom-block-title">Error común</p><p>Muchos jugadores experimentados pasan años perfeccionando la técnica que ya tienen, cuando lo que realmente necesitan es desarrollar la fuerza mental para ejecutarla bajo presión.</p><p><strong>No necesitas un mejor movimiento de brazos. Necesitas una mente más tranquila.</strong></p></div><h3 id="el-camino-a-seguir" tabindex="-1">El camino a seguir <a class="header-anchor" href="#el-camino-a-seguir" aria-label="Permalink to &quot;El camino a seguir&quot;">​</a></h3><p><strong>Para mejores tomas (nuevas capacidades):</strong></p><ul><li>Explora la <a href="/es/técnico/lanzamientos">Paleta de Lanzamientos</a></li><li>Elige un nuevo lanzamiento específico para desarrollar</li><li>Practica la ejecución técnica</li></ul><p><strong>Para más disparos (consistencia bajo presión):</strong></p><ul><li>Trabajar la <a href="/es/educacion/fuerza-mental/">Fuerza Mental</a></li><li>Aprende a acceder a <a href="/es/educacion/la-zona/">La Zona</a></li><li>Desarrollar <a href="/es/educacion/fuerza-mental/rutina-previa-al-tiro">Rutinas Previas al Tiro</a></li></ul><h2 id="nuestra-perspectiva" tabindex="-1">Nuestra perspectiva <a class="header-anchor" href="#nuestra-perspectiva" aria-label="Permalink to &quot;Nuestra perspectiva&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">No necesitas dominarlo todo</p><p><strong>No es necesario que domines todas las técnicas</strong>, pero comprender la paleta completa de posibilidades te ayudará a:</p><ul><li>✅ Conozca lo que es posible</li><li>✅ Tomar decisiones informadas sobre qué desarrollar</li><li>✅ Apreciar el juego a un nivel más profundo</li><li>✅ Entender lo que pueden hacer los jugadores de élite</li></ul></div>',33)),(r(),t(c,null,{default:s(()=>[l(f,{id:"mermaid-277",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BConocimientos%20t%C3%A9cnicos%5D%20--%3E%20B%5BDecisiones%20informadas%5D%0A%20%20%20%20B%20--%3E%20C%5BDesarrollo%20Enfocado%5D%0A%20%20%20%20C%20--%3E%20D%5BDominio%20de%20habilidades%20clave%5D%0A%20%20%20%20D%20--%3E%20E%5BAcceso%20al%20estado%20de%20flujo%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20D%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:s(()=>[...u[1]||(u[1]=[n(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=i('<div class="info custom-block"><p class="custom-block-title">El objetivo</p><p>Si tiene un enfoque técnico y desea ampliar su repertorio, esta sección describe el objetivo final: la paleta completa de lanzamientos disponibles para un jugador de petanca.</p><p><strong>Recuerda:</strong> El objetivo no es dominarlo todo. Es tener la base técnica suficiente para entrar en la zona y dejar que tu cuerpo elija el lanzamiento correcto de forma natural.</p></div><h2 id="temas" tabindex="-1">Temas <a class="header-anchor" href="#temas" aria-label="Permalink to &quot;Temas&quot;">​</a></h2><h3 id="paleta-de-lanzamientos" tabindex="-1"><a href="/es/técnico/lanzamientos">Paleta de Lanzamientos</a> <a class="header-anchor" href="#paleta-de-lanzamientos" aria-label="Permalink to &quot;[Paleta de Lanzamientos](/es/técnico/lanzamientos)&quot;">​</a></h3><p>¿Qué lanzamientos hay? Un resumen completo de las posibilidades técnicas en la petanca.</p><div class="tip custom-block"><p class="custom-block-title">Después de la técnica, ¿qué sigue?</p><p>Una vez que tienes una técnica sólida, el verdadero crecimiento proviene de:</p><ul><li><strong><a href="/es/educacion/la-zona/">La Zona</a></strong> - Acceso a estados de flujo</li><li><strong><a href="/es/educacion/fuerza-mental/">Fuerza mental</a></strong> - Manejo de la presión</li><li><strong><a href="/es/educacion/entrenamiento/">Métodos de entrenamiento</a></strong> - Cómo practicar eficazmente</li></ul></div>',5))])}]]);export{u as __pageData,d as default};
